using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
namespace CircuitoStudio {
public sealed class FaultExtremesForm:Form {
readonly Project project;readonly FaultExtremeProfile draft;readonly List<Action> readers=new List<Action>();readonly TextBox details=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Dock=DockStyle.Bottom,Height=240};readonly DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells};public bool Changed{get;private set;}
public FaultExtremesForm(Project p){project=p;draft=p.FaultExtremes==null?new FaultExtremeProfile{LineVoltageV=p.Source.LineVoltage,FrequencyHz=p.Frequency}:p.FaultExtremes.Copy();Text="Extremos de curto3F/LL e contribuições iniciais";Size=new Size(1500,950);MinimumSize=new Size(1200,760);Font=new Font("Segoe UI",10);var split=new SplitContainer{Dock=DockStyle.Fill};split.Size=new Size(1460,850);split.SplitterDistance=650;var tabs=new TabControl{Dock=DockStyle.Fill};var global=new TabPage("Limites / alcance");global.Controls.Add(TypedFields.Create(draft,readers));tabs.TabPages.Add(global);tabs.TabPages.Add(CaseTab("Mínimo",draft.Minimum));tabs.TabPages.Add(CaseTab("Máximo",draft.Maximum));split.Panel1.Controls.Add(tabs);var actions=new FlowLayoutPanel{Dock=DockStyle.Top,Height=80};Add(actions,"Calcular cópia",()=>EvaluateDraft(false));Add(actions,"Salvar estudo",()=>EvaluateDraft(true));Add(actions,"CSV salvo",()=>{using(var d=new SaveFileDialog{Filter="Extremos CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)FaultExtremes.Export(project,d.FileName);});Add(actions,"Remover estudo",()=>{project.FaultExtremes=null;Changed=true;grid.Rows.Clear();details.Text="Estudo removido.";});foreach(var label in new[]{"Cenário","Circuito","Local","Falta","Ik inicial (A)","Fonte","|IA| (A)","|IB| (A)","|IC| (A)"})grid.Columns.Add(label,label);split.Panel2.Controls.Add(grid);split.Panel2.Controls.Add(details);split.Panel2.Controls.Add(actions);Controls.Add(split);details.Text="Dois cenários completos e documento de cobertura exigidos. Impedâncias totais por ramo já corrigidas à temperatura/frequência e por fonte nas sequências1/2; não se preenchem de Icc nominal. Fontes internas simétricas em fase; sem corrente pré-falta, terra, conversor limitado ou dinâmica de máquina. Corrente inicial pode diferir da sustentada. Circuitos monofásicos fora do escopo. Calcular cópia não altera o projeto. Cada ramo guarda vínculo com geometria/seção/referência atuais; novo vínculo só por edição explícita.";}
void Add(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true};b.Click+=(s,e)=>{try{action();}catch(Exception ex){details.Text="Operação recusada: "+ex.Message;}};parent.Controls.Add(b);}
bool Edit(object obj,string title){using(var f=new Form{Text=title,Size=new Size(760,650),MinimumSize=new Size(700,580),Font=Font,StartPosition=FormStartPosition.CenterParent}){var reads=new List<Action>();var fields=TypedFields.Create(obj,reads);var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=55};var error=new Label{Dock=DockStyle.Bottom,Height=60};var ok=new Button{Text="Aplicar à cópia",AutoSize=true};ok.Click+=(s,e)=>{try{foreach(var read in reads)read();var source=obj as ExtremeSource;if(source!=null)source.Validate();var branch=obj as ExtremeBranch;if(branch!=null)branch.Validate();f.DialogResult=DialogResult.OK;f.Close();}catch(Exception ex){error.Text=ex.Message;}};bottom.Controls.Add(ok);f.Controls.Add(fields);f.Controls.Add(error);f.Controls.Add(bottom);return f.ShowDialog(this)==DialogResult.OK;}}
TabPage CaseTab(string title,ExtremeCase config){var tab=new TabPage(title);var fields=TypedFields.Create(config,readers);fields.Dock=DockStyle.Top;fields.Height=160;var container=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};container.RowStyles.Add(new RowStyle(SizeType.Absolute,160));container.RowStyles.Add(new RowStyle(SizeType.Percent,50));container.RowStyles.Add(new RowStyle(SizeType.Percent,50));container.RowStyles.Add(new RowStyle(SizeType.Absolute,65));container.Controls.Add(fields,0,0);var sources=new ListBox{Dock=DockStyle.Fill};var branches=new ListBox{Dock=DockStyle.Fill};Action refresh=()=>{sources.Items.Clear();foreach(var x in config.Sources)sources.Items.Add(x.Id+" @"+x.BoardId+" · "+(x.Active.HasValue?x.Active.Value?"ativa":"inativa":"estado?"));branches.Items.Clear();foreach(var x in config.Branches)branches.Items.Add(x.CircuitId+" · "+x.ConductorTemperatureC+" °C · "+x.Reference);};
var sourceBox=new GroupBox{Text="Fontes (Ω por fase; sequência1/2)",Dock=DockStyle.Fill};var sb=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=72};sourceBox.Controls.Add(sources);sourceBox.Controls.Add(sb);Add(sb,"Nova",()=>{var x=new ExtremeSource{BoardId=project.Boards.FirstOrDefault()==null?"":project.Boards[0].Id};if(Edit(x,title+" — fonte")){config.Sources.Add(x);refresh();}});Add(sb,"Editar",()=>{int i=sources.SelectedIndex;if(i<0)return;var x=config.Sources[i].Copy();if(Edit(x,title+" — fonte")){config.Sources[i]=x;refresh();}});Add(sb,"Excluir",()=>{if(sources.SelectedIndex>=0)config.Sources.RemoveAt(sources.SelectedIndex);refresh();});Add(sb,"Importar CSV",()=>{using(var d=new OpenFileDialog{Filter="Fontes CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var rows=FaultExtremes.ImportSources(d.FileName);config.Sources=rows;refresh();}});Add(sb,"Exportar CSV",()=>{using(var d=new SaveFileDialog{Filter="Fontes CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)FaultExtremes.ExportSources(config.Sources,d.FileName);});
var branchBox=new GroupBox{Text="Ramos trifásicos (Ω TOTAIS, não Ω/km)",Dock=DockStyle.Fill};var bb=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=72};branchBox.Controls.Add(branches);branchBox.Controls.Add(bb);Add(bb,"Ramos faltantes",()=>{foreach(var c in project.Boards.SelectMany(b=>b.Circuits).Where(c=>c.Phases==PhaseMode.Trifasico))if(!config.Branches.Any(x=>x.CircuitId==c.Id))config.Branches.Add(new ExtremeBranch{CircuitId=c.Id,CircuitContext=FaultExtremes.Context(project,c)});refresh();});Add(bb,"Editar / revincular",()=>{int i=branches.SelectedIndex;if(i<0)return;var x=config.Branches[i].Copy();var c=project.Boards.SelectMany(b=>b.Circuits).FirstOrDefault(item=>item.Id==x.CircuitId);if(c==null)throw new InvalidDataException("Circuito removido; exclua este ramo.");if(Edit(x,title+" — "+x.CircuitId+"; aplicar atualiza vínculo físico")){if(x.CircuitId!=c.Id)throw new InvalidDataException("ID do ramo não pode ser trocado.");x.CircuitContext=FaultExtremes.Context(project,c);config.Branches[i]=x;refresh();}});Add(bb,"Excluir",()=>{if(branches.SelectedIndex>=0)config.Branches.RemoveAt(branches.SelectedIndex);refresh();});Add(bb,"Importar CSV",()=>{using(var d=new OpenFileDialog{Filter="Ramos CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var rows=FaultExtremes.ImportBranches(d.FileName);config.Branches=rows;refresh();}});Add(bb,"Exportar CSV",()=>{using(var d=new SaveFileDialog{Filter="Ramos CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)FaultExtremes.ExportBranches(config.Branches,d.FileName);});container.Controls.Add(sourceBox,0,1);container.Controls.Add(branchBox,0,2);container.Controls.Add(new Label{Dock=DockStyle.Fill,Text="IDs de quadros: "+String.Join(", ",project.Boards.Select(b=>b.Id))+". Fontes dos dois cenários exigem mesmos IDs/tipo/local, com estado explícito. Dados vazios não aprovam."},0,3);tab.Controls.Add(container);refresh();return tab;}
public FaultExtremeResult EvaluateDraft(bool commit){foreach(var read in readers)read();draft.Validate();var old=project.FaultExtremes;project.FaultExtremes=draft.Copy();bool saved=false;try{project.Validate();var result=FaultExtremes.Run(project);grid.Rows.Clear();foreach(var point in result.Points){grid.Rows.Add(point.Scenario,point.CircuitId,point.Location,point.Fault,point.CurrentA.ToString("N4"),"TOTAL",point.FaultCurrent[0].Magnitude.ToString("N4"),point.FaultCurrent[1].Magnitude.ToString("N4"),point.FaultCurrent[2].Magnitude.ToString("N4"));foreach(var source in point.Contributions)grid.Rows.Add("",point.CircuitId,point.Location,point.Fault,"",source.SourceId,source.Current[0].Magnitude.ToString("N4"),source.Current[1].Magnitude.ToString("N4"),source.Current[2].Magnitude.ToString("N4"));}details.Text=result.Status+"\r\n"+result.Detail;if(commit){saved=true;Changed=true;}return result;}finally{if(!saved)project.FaultExtremes=old;}}
}
partial class Studio{void ConfigureFaultExtremes(){using(var f=new FaultExtremesForm(project)){f.ShowDialog(this);if(f.Changed)Change();}}}
}
